import org.junit.Test
import org.junit.Assert

class Tests {
    @Test
    fun testTotal() {
        val score = MatchScore(4215, 20, 45)
        Assert.assertEquals(65, score.total())
    }

    @Test
    fun testTotalZero() {
        val score = MatchScore(1234, 0, 0)
        Assert.assertEquals(0, score.total())
    }

    @Test
    fun testToStringContainsValues() {
        val score = MatchScore(4215, 20, 45)
        val str = score.toString()
        Assert.assertTrue(str.contains("4215"))
        Assert.assertTrue(str.contains("20"))
        Assert.assertTrue(str.contains("45"))
    }

    @Test
    fun testEquality() {
        val a = MatchScore(4215, 20, 45)
        val b = MatchScore(4215, 20, 45)
        Assert.assertEquals(a, b)
    }
}
